import{_ as t,o,c as r,ag as a}from"./chunks/framework.8tqBsFWt.js";const _=JSON.parse('{"title":"Reports, Alerts & Calendar Tools","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools/reports.md","filePath":"reference/tools/reports.md"}'),d={name:"reference/tools/reports.md"};function s(n,e,i,c,l,p){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="reports-alerts-calendar-tools" tabindex="-1">Reports, Alerts &amp; Calendar Tools <a class="header-anchor" href="#reports-alerts-calendar-tools" aria-label="Permalink to &quot;Reports, Alerts &amp; Calendar Tools&quot;">​</a></h1><hr><h2 id="get_project_accrual_basis" tabindex="-1">get_project_accrual_basis <a class="header-anchor" href="#get_project_accrual_basis" aria-label="Permalink to &quot;get_project_accrual_basis {#get_project_accrual_basis}&quot;">​</a></h2><p>Revenue recognised, cost accrued, and net for a project as of any date. <strong>Manager/Owner.</strong></p><p>Use this tool for any question involving:</p><ul><li>&quot;What&#39;s the accrual basis for [project]?&quot;</li><li>&quot;What will the P&amp;L be on [date]?&quot;</li><li>&quot;How much revenue have we recognised?&quot;</li><li>&quot;What&#39;s the accrued cost so far?&quot;</li></ul><p><strong>Reads from</strong>: <code>01. Time Entries</code>, <code>02. Projects</code>, <code>03. Users</code>, <code>13. Rate_History</code>, <code>14. Liabilities</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td></td></tr><tr><td><code>project_name</code></td><td>Project to query</td></tr><tr><td><code>as_of</code></td><td><code>YYYY-MM-DD</code> — defaults to today. Past dates clip entries; future dates use locked-in entries + deterministic liability accrual.</td></tr></tbody></table><p><strong>Returns:</strong></p><ul><li><code>revenue_recognised</code> — earned revenue as of <code>as_of</code> per project type (see below)</li><li><code>labour_cost</code> — hours × effective cost rate for each logged entry on or before <code>as_of</code></li><li><code>liability_cost</code> — pro-rata vendor fixed payment agreement cost: <code>agreed_amount × elapsed_days / total_days</code></li><li><code>total_cost</code> — <code>labour_cost + liability_cost</code></li><li><code>net</code> — <code>revenue_recognised − total_cost</code></li><li><code>breakdown.liability_overrides</code> — per-vendor: <code>agreed_amount</code>, <code>accrued_cost</code>, <code>description</code></li><li><code>breakdown.per_user</code> — per-person labour detail: <code>user_id</code>, <code>total_hours</code>, <code>total_cost</code>, <code>rate_changed</code>, <code>segments[]</code> (one per rate period; each segment has <code>rate</code>, <code>hours</code>, <code>cost</code>, <code>effectiveFrom</code>)</li><li><code>breakdown.rate_adjusted</code> — <code>true</code> if any user&#39;s cost rate changed during the period</li></ul><p><strong>Revenue rules by project type:</strong></p><table tabindex="0"><thead><tr><th>Type</th><th>Revenue formula</th></tr></thead><tbody><tr><td>T&amp;M</td><td><code>hours_logged × billing_rate</code></td></tr><tr><td>Fixed Price</td><td><code>(hours_logged / hours_budget) × contract_value</code>, capped at 100%</td></tr><tr><td>Retainer / Agile</td><td>Sum across active period/sprint children: <code>(child_hours / child_budget) × child_contract_value</code></td></tr><tr><td>Pro Bono</td><td>$0</td></tr><tr><td>Internal</td><td>$0</td></tr></tbody></table><p><strong>Future dates</strong>: revenue reflects only entries already in the system — VERA never extrapolates from pace. Liability cost grows deterministically to the project deadline regardless of allocations.</p><p><strong>Example queries:</strong></p><ul><li>&quot;What&#39;s the accrual basis for the Humbug project?&quot; → <code>as_of</code> omitted (defaults to today)</li><li>&quot;What will the accrual basis be two weeks from today?&quot; → <code>as_of = &lt;today + 14 days&gt;</code></li><li>&quot;What was the P&amp;L on March 15th?&quot; → <code>as_of = 2026-03-15</code></li></ul><hr><h2 id="generate_monthly_report" tabindex="-1">generate_monthly_report <a class="header-anchor" href="#generate_monthly_report" aria-label="Permalink to &quot;generate_monthly_report {#generate_monthly_report}&quot;">​</a></h2><p>Portfolio P&amp;L for the current (or specified) month. <strong>Owner/Manager</strong> — role-filtered results.</p><p><strong>Reads from</strong>: <code>01. Time Entries</code>, <code>02. Projects</code>, <code>22. Projects Master</code>, <code>13. Rate_History</code>, <code>14. Liabilities</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td></td></tr><tr><td><code>month</code></td><td><code>YYYY-MM</code> — defaults to current month</td></tr></tbody></table><p><strong>Returns:</strong></p><ul><li>Per-project: name, hours_logged, budget_hours, utilisation%, burn_rate_status, revenue (Owner), cost (Owner), margin (Owner)</li><li><code>total_revenue_overrun</code>: revenue at risk from over-budget projects (Owner)</li><li><code>open_items_total</code>: unresolved items count</li><li>Summary: over_budget_count, under_utilised_count</li></ul><p><strong>Status emojis</strong>: 🚨 critical_overpace | ⚠️ warning_overpace | ✅ on_track | 📉 warning_underpace | 🔴 critical_underpace | ➖ no status</p><hr><h2 id="get_export_data" tabindex="-1">get_export_data <a class="header-anchor" href="#get_export_data" aria-label="Permalink to &quot;get_export_data {#get_export_data}&quot;">​</a></h2><p>Raw export of all operational data for external analysis. <strong>Owner only.</strong></p><p><strong>Reads from</strong>: All operational sheets</p><p><strong>Returns</strong>: time_entries, projects, users, tasks, clients — full data without role-filtering</p><p>This is also triggered automatically when a user asks to &quot;export&quot; or requests a CSV in conversation.</p><hr><h2 id="get_proactive_alerts" tabindex="-1">get_proactive_alerts <a class="header-anchor" href="#get_proactive_alerts" aria-label="Permalink to &quot;get_proactive_alerts {#get_proactive_alerts}&quot;">​</a></h2><p>Current alerts across burn rate, stale items, and envelope gaps. <strong>Manager/Owner.</strong></p><p><strong>No parameters required</strong> (beyond <code>requesting_user_slack_id</code>).</p><p><strong>Returns grouped by type:</strong></p><table tabindex="0"><thead><tr><th>Type</th><th>Severity</th><th>Trigger</th></tr></thead><tbody><tr><td><code>burn_rate</code></td><td>critical / warning</td><td>Retainer pacing over/under budget</td></tr><tr><td><code>stale_item</code></td><td>warning</td><td>Unresolved item open &gt; N days</td></tr><tr><td><code>allocation_gap</code></td><td>info</td><td>Project with no coverage in upcoming weeks</td></tr></tbody></table><p><strong>Interpretation:</strong></p><ul><li><code>critical</code> → immediate action required</li><li><code>warning</code> → action needed soon</li><li><code>info</code> → worth reviewing</li></ul><p>Never auto-resolve alerts — always let the Manager decide the action.</p><hr><h2 id="get_unresolved_items" tabindex="-1">get_unresolved_items <a class="header-anchor" href="#get_unresolved_items" aria-label="Permalink to &quot;get_unresolved_items {#get_unresolved_items}&quot;">​</a></h2><p>Open operational issues that need attention. <strong>Manager/Owner.</strong></p><p><strong>Reads from</strong>: <code>11. Unresolved_Items</code>, <code>02. Projects</code>, <code>03. Users</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td></td></tr><tr><td><code>status</code></td><td><code>&quot;open&quot;</code> (default), <code>&quot;resolved&quot;</code>, <code>&quot;dismissed&quot;</code></td></tr></tbody></table><p><strong>Item types:</strong></p><ul><li><code>sick_conflict</code> — user sick while they have active project envelopes</li><li><code>leave_conflict</code> — leave logged while they have active project envelopes</li><li><code>pto_conflict</code> — PTO approved while they have active project envelopes</li><li><code>time_off_request</code> — pending time off request awaiting approval</li></ul><p>Managers see only items for their assigned projects. Owners see all.</p><hr><h2 id="resolve_item" tabindex="-1">resolve_item <a class="header-anchor" href="#resolve_item" aria-label="Permalink to &quot;resolve_item {#resolve_item}&quot;">​</a></h2><p>Mark an unresolved item as resolved — use when the Manager has taken action (e.g. reassigned work, updated envelopes). <strong>Manager/Owner.</strong></p><p><strong>Updates</strong>: <code>11. Unresolved_Items</code> cols G:I</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>item_id</code>, <code>resolution_summary</code></p><hr><h2 id="dismiss_item" tabindex="-1">dismiss_item <a class="header-anchor" href="#dismiss_item" aria-label="Permalink to &quot;dismiss_item {#dismiss_item}&quot;">​</a></h2><p>Dismiss an unresolved item without action — use when the Manager acknowledges the issue but decides no action is needed. <strong>Manager/Owner.</strong></p><p><strong>Updates</strong>: <code>11. Unresolved_Items</code> col G (status → <code>&quot;dismissed&quot;</code>)</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>item_id</code></p><hr><h2 id="get_resolution_options" tabindex="-1">get_resolution_options <a class="header-anchor" href="#get_resolution_options" aria-label="Permalink to &quot;get_resolution_options {#get_resolution_options}&quot;">​</a></h2><p>Ranked list of resolution options for an unresolved item, with consequences. <strong>Manager/Owner.</strong></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>item_id</code></p><p><strong>Returns</strong>: ranked options, each with:</p><ul><li>Action description</li><li>Consequence</li><li>Tools needed to execute</li></ul><p>Options are ranked by disruption level (lowest disruption first). Always present consequences to the Manager before asking them to choose. Never auto-execute an option.</p><hr><h2 id="add_company_holiday" tabindex="-1">add_company_holiday <a class="header-anchor" href="#add_company_holiday" aria-label="Permalink to &quot;add_company_holiday {#add_company_holiday}&quot;">​</a></h2><p>Add a holiday or company event to the calendar. <strong>Owner only.</strong></p><p><strong>Writes to</strong>: <code>12. Company_Calendar</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>date</code>, <code>name</code>, <code>type</code> (<code>&quot;holiday&quot;</code> or <code>&quot;company_event&quot;</code>)</p><p>Only <code>&quot;holiday&quot;</code> entries block PTO requests and are excluded from leave date ranges.</p><hr><h2 id="list_company_holidays" tabindex="-1">list_company_holidays <a class="header-anchor" href="#list_company_holidays" aria-label="Permalink to &quot;list_company_holidays {#list_company_holidays}&quot;">​</a></h2><p>All calendar entries.</p><p><strong>Reads from</strong>: <code>12. Company_Calendar</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code></p><hr><h2 id="remove_company_holiday" tabindex="-1">remove_company_holiday <a class="header-anchor" href="#remove_company_holiday" aria-label="Permalink to &quot;remove_company_holiday {#remove_company_holiday}&quot;">​</a></h2><p>Delete a calendar entry by ID. <strong>Owner only.</strong></p><p><strong>Deletes from</strong>: <code>12. Company_Calendar</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>holiday_id</code></p><blockquote><p>To find the holiday ID, call <code>list_company_holidays</code> first.</p></blockquote><hr><h2 id="get_work_week" tabindex="-1">get_work_week <a class="header-anchor" href="#get_work_week" aria-label="Permalink to &quot;get_work_week {#get_work_week}&quot;">​</a></h2><p>Return the current work week configuration. <strong>Any role.</strong></p><p>Returns <code>work_week.days</code> (array of day abbreviations: <code>Mon</code>–<code>Sun</code>) and <code>work_week.hours_per_day</code>. If the tenant has never called <code>set_work_week</code>, the defaults are returned: Mon–Fri, 8 hours/day.</p><hr><h2 id="set_work_week" tabindex="-1">set_work_week <a class="header-anchor" href="#set_work_week" aria-label="Permalink to &quot;set_work_week {#set_work_week}&quot;">​</a></h2><p>Configure the tenant&#39;s working days. <strong>Owner only.</strong></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>days</code> (array of abbreviations: <code>Mon</code>–<code>Sun</code>), <code>hours_per_day</code> (number)</p><p>Default is Monday–Friday, 8 hours/day. Work week settings affect:</p><ul><li>Leave date range calculations (weekends skipped)</li><li>PTO hour defaults</li><li>Capacity forecast calculations</li></ul>',93)])])}const h=t(d,[["render",s]]);export{_ as __pageData,h as default};
